declare(strict_types=1);
function icon(string $name): string {
    $paths = [
        'grid'=>'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
        'chart'=>'<path d="M4 4v16h16M8 15v-4m5 4V7m5 8v-6"/>',
        'retry'=>'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',
        'book'=>'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-6-2-10 1Z"/>',
        'flag'=>'<path d="M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',
        'check'=>'<path d="m5 12 4 4L19 6"/>',
        'moon'=>'<path d="M20.8 13A9 9 0 0 1 11 3.2 9 9 0 1 0 20.8 13Z"/>',
        'settings'=>'<path d="m9 3-.5 3-2 1-2.8-1-2 3.5 2.3 2v2.3l-2.3 2 2 3.5 2.8-1 2 1 .5 3h4l.5-3 2-1 2.8 1 2-3.5-2.3-2V11l2.3-2-2-3.5-2.8 1-2-1L13 3Z"/><circle cx="11" cy="12" r="3"/>',
        'clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
        'cross'=>'<path d="m6 6 12 12M18 6 6 18"/>',
        'chevron'=>'<path d="m9 5 7 7-7 7"/>',
        'shield'=>'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
    ];
    return '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['book']).'</svg>';
}
function token_fields(?array $run = null): void {
    echo '<input type="hidden" name="csrf" value="'.e(csrf()).'">';
    if ($run) echo '<input type="hidden" name="run" value="'.e($run['id']).'"><input type="hidden" name="revision" value="'.e($run['revision']).'">';
}
function solution(array $result, bool $expanded = true): void {
    $q=$result['question'];
    echo '<div class="solution"><div class="solution-title">'.icon('book').'<h3>Comprendre la réponse</h3></div><p>'.e($q['explanation']).'</p><div class="rationale-list">';
    foreach ($q['choices'] as $letter=>$choice) {
        $selected=!empty($result['answers'][$letter]);
        echo '<div class="rationale '.($choice['correct']?'answer-true':'answer-false').'"><span class="letter">'.$letter.'</span><div><div class="rationale-top"><strong>'.($choice['correct']?'Bonne réponse':'Faux').'</strong><span class="student-choice '.($selected?'selected':'').'">'.($selected?'✓ Votre choix':'Non sélectionnée').'</span></div><p>'.e($choice['text']).'</p><p class="explain">'.e($q['why'][$letter]).'</p></div></div>';

    }
    echo '</div><p class="source">'.e($q['source']).'</p>';
    if (!empty($result['note'])) echo '<div class="personal-note"><strong>Votre raisonnement</strong><p>'.nl2br(e($result['note'])).'</p></div>';
    echo '</div>';
}
